"""Bidirectional spec/implementation drift detection logic."""

from __future__ import annotations

import hashlib
import json
import re
from dataclasses import dataclass, field
from datetime import datetime, timezone
from enum import Enum
from pathlib import Path
from typing import Any

REQUIREMENT_RE = re.compile(r"^###\s+(R-\d+)\s+[—-]\s+(.*)$", re.M)

FRONTMATTER_RE = re.compile(r"^---\r?\n(.*?)\r?\n---\r?\n?(.*)$", re.S)


def _hash_text(s: str) -> str:
    return hashlib.sha256(s.encode("utf-8")).hexdigest()


def hash_file(path: Path) -> str:
    data = path.read_bytes()
    return hashlib.sha256(data).hexdigest()


class Drift(str, Enum):
    IN_SYNC = "IN_SYNC"
    SPEC_AHEAD = "SPEC_AHEAD"
    CODE_AHEAD = "CODE_AHEAD"
    CONFLICT = "CONFLICT"
    NEW = "NEW"
    REMOVED = "REMOVED"
    UNTRACED = "UNTRACED"
    BROKEN_TRACE = "BROKEN_TRACE"


@dataclass
class Requirement:
    id: str
    title: str
    status: str
    acceptance: list[str]
    traces: list[str]
    spec_hash: str


@dataclass
class Spec:
    id: str
    title: str
    version: int
    status: str
    path: Path
    requirements: dict[str, Requirement]
    raw: str


@dataclass
class RequirementReport:
    id: str
    drift: Drift
    details: list[str] = field(default_factory=list)


@dataclass
class DriftReport:
    spec_id: str
    requirements: list[RequirementReport] = field(default_factory=list)

    def by_id(self) -> dict[str, RequirementReport]:
        return {r.id: r for r in self.requirements}

    @property
    def has_drift(self) -> bool:
        return any(r.drift is not Drift.IN_SYNC for r in self.requirements)


def parse_spec_file(path: Path) -> Spec:
    text = path.read_text(encoding="utf-8")
    return parse_spec(text, path)


def parse_spec(text: str, path: Path | None = None) -> Spec:
    m = FRONTMATTER_RE.match(text)
    if not m:
        raise ValueError(f"No frontmatter found in {path or '<text>'}")

    fm_str, body = m.group(1), m.group(2)

    fm: dict[str, Any] = {}
    last_key: str | None = None
    for raw in fm_str.splitlines():
        line = raw.rstrip("\r")
        colon = line.find(":")
        if colon > 0 and not line.startswith(" "):
            key = line[:colon].strip()
            val = line[colon + 1 :].strip()
            if re.match(r"^(>[+-]?|\|[+-]?)$", val):
                fm[key] = ""
            else:
                fm[key] = val.strip('"').strip("'") if (val.startswith('"') and val.endswith('"')) or (val.startswith("'") and val.endswith("'")) else val
            last_key = key
        elif last_key is not None and line.strip():
            fm[last_key] = f"{fm.get(last_key, '')} {line.strip()}".strip()

    spec_id = str(fm.get("id") or fm.get("name") or "")
    title = str(fm.get("title") or spec_id)
    try:
        version = int(fm.get("version") or 1)
    except Exception:
        version = 1
    status = str(fm.get("status") or "draft")

    reqs: dict[str, Requirement] = {}

    # Split requirements by headings
    # Collect headings positions
    headings = list(REQUIREMENT_RE.finditer(body))
    for i, h in enumerate(headings):
        rid = h.group(1)
        rtitle = h.group(2).strip()
        start = h.start()
        end = headings[i + 1].start() if i + 1 < len(headings) else len(body)
        block = body[start:end]

        rstatus = "draft"
        mstatus = re.search(r"^-\s*status:\s*(\S+)", block, re.M)
        if mstatus:
            rstatus = mstatus.group(1)

        acceptance: list[str] = []
        macc = re.search(r"^-\s*acceptance:\s*$", block, re.M)
        if macc:
            acc_start = macc.end()
            # find next top-level bullet or end of block
            mnext = re.search(r"^-\s+\w+:", block[acc_start:], re.M)
            acc_end = acc_start + mnext.start() if mnext else len(block)
            acc_block = block[acc_start:acc_end]
            for line in acc_block.splitlines():
                line = line.rstrip()
                if not line.strip():
                    continue
                mitem = re.match(r"^\s*-\s+(.*)$", line)
                if mitem:
                    acceptance.append(mitem.group(1).strip())
                elif line.strip().startswith("-"):
                    pass

        traces: list[str] = []
        mtr = re.search(r"^-\s*traces:\s*$", block, re.M)
        if mtr:
            tr_start = mtr.end()
            mnext = re.search(r"^-\s+\w+:", block[tr_start:], re.M)
            tr_end = tr_start + mnext.start() if mnext else len(block)
            tr_block = block[tr_start:tr_end]
            for line in tr_block.splitlines():
                line = line.rstrip()
                if not line.strip():
                    continue
                mitem = re.match(r"^\s*-\s+(.*)$", line)
                if mitem:
                    v = mitem.group(1).strip()
                    if v:
                        traces.append(v)

        spec_hash = _spec_hash_block(rtitle, rstatus, acceptance)

        reqs[rid] = Requirement(
            id=rid,
            title=rtitle,
            status=rstatus,
            acceptance=acceptance,
            traces=traces,
            spec_hash=spec_hash,
        )

    return Spec(
        id=spec_id,
        title=title,
        version=version,
        status=status,
        path=path or Path("."),
        requirements=reqs,
        raw=text,
    )


def _spec_hash_block(title: str, status: str, acceptance: list[str]) -> str:
    parts = [f"title: {title}", f"status: {status}"]
    if acceptance:
        parts.append("acceptance:")
        for a in acceptance:
            parts.append(f"  - {a}")
    norm = "\n".join(parts)
    return _hash_text(norm)


def load_state(path: Path) -> dict[str, Any]:
    if not path.exists():
        return {}
    data = path.read_text(encoding="utf-8")
    try:
        return json.loads(data)
    except json.JSONDecodeError:
        return {}


def save_state(path: Path, state: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(state, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def record_state(spec: Spec, root: Path) -> dict[str, Any]:
    root = root.resolve()
    reqs_state: dict[str, Any] = {}
    for rid, req in spec.requirements.items():
        evidence: dict[str, str] = {}
        for t in req.traces:
            trace_path = t.split("::", 1)[0]
            fp = (root / trace_path).resolve()
            try:
                if fp.exists():
                    evidence[t] = hash_file(fp)
            except Exception:
                # Skip missing on record; broken trace detected on check.
                pass
        reqs_state[rid] = {
            "spec_hash": req.spec_hash,
            "evidence": evidence,
        }
    state: dict[str, Any] = {
        "spec_id": spec.id,
        "recorded_at": datetime.now(timezone.utc).isoformat(),
        "requirements": reqs_state,
    }
    return state


def compute_report(spec: Spec, state: dict[str, Any], root: Path) -> DriftReport:
    root = root.resolve()
    spec_reqs = spec.requirements
    state_reqs = state.get("requirements", {}) if state else {}

    all_ids = set(spec_reqs) | set(state_reqs)
    reports: list[RequirementReport] = []

    for rid in sorted(all_ids):
        if rid not in spec_reqs and rid in state_reqs:
            reports.append(RequirementReport(id=rid, drift=Drift.REMOVED, details=[]))
            continue
        if rid in spec_reqs and rid not in state_reqs:
            reports.append(RequirementReport(id=rid, drift=Drift.NEW, details=[]))
            continue
        req = spec_reqs[rid]
        rec = state_reqs[rid]
        traces = req.traces

        if not traces:
            reports.append(RequirementReport(id=rid, drift=Drift.UNTRACED, details=[]))
            continue

        evidence_now: dict[str, str] = {}
        broken = False
        missing_list: list[str] = []
        for t in traces:
            trace_path_str = t.split("::", 1)[0]
            fp = (root / trace_path_str).resolve()
            if not fp.exists():
                broken = True
                missing_list.append(trace_path_str)
                continue
            try:
                evidence_now[t] = hash_file(fp)
            except Exception:
                broken = True
                missing_list.append(trace_path_str)

        spec_changed = req.spec_hash != rec.get("spec_hash")
        ev_rec = rec.get("evidence", {}) or {}
        ev_changed = evidence_now != ev_rec

        if broken:
            details = [f"missing trace: {m}" for m in missing_list]
            reports.append(RequirementReport(id=rid, drift=Drift.BROKEN_TRACE, details=details))
            continue
        if spec_changed and ev_changed:
            reports.append(RequirementReport(id=rid, drift=Drift.CONFLICT, details=[]))
            continue
        if spec_changed:
            reports.append(RequirementReport(id=rid, drift=Drift.SPEC_AHEAD, details=[]))
            continue
        if ev_changed:
            reports.append(RequirementReport(id=rid, drift=Drift.CODE_AHEAD, details=[]))
            continue
        reports.append(RequirementReport(id=rid, drift=Drift.IN_SYNC, details=[]))

    return DriftReport(spec_id=spec.id, requirements=reports)

