@app.command("check")
def check(
    feature: Optional[str] = typer.Argument(None, help="Feature/spec directory name under specs/"),
    root: Path = typer.Option(Path.cwd(), help="Repo root"),
    record: bool = typer.Option(False, help="Write/update sync state after checking"),
    json_output: bool = typer.Option(False, "--json", help="Emit JSON report"),
) -> None:
    root = root.resolve()
    specs_root = root / "specs"
    if not specs_root.exists():
        typer.echo("No specs/ directory found.", err=True)
        raise typer.Exit(1)

    spec_paths = []
    if feature:
        sp = specs_root / feature / "spec.md"
        if sp.exists():
            spec_paths = [sp]
        else:
            typer.echo(f"Spec not found: {sp}", err=True)
            raise typer.Exit(1)
    else:
        for p in specs_root.rglob("spec.md"):
            if p.parent.name != "_template":
                spec_paths.append(p)

    any_drift = False
    reports = []
    for sp in sorted(spec_paths):
        try:
            spec = spec_sync.parse_spec_file(sp)
        except Exception as e:
            typer.echo(f"Failed to parse {sp}: {e}", err=True)
            raise typer.Exit(1)
        state_path = sp.parent / ".sync.json"
        state = spec_sync.load_state(state_path)
        report = spec_sync.compute_report(spec, state, root)
        if report.has_drift:
            any_drift = True
        reports.append(report)

        if not json_output:
            typer.echo(f"== {spec.id} ({sp.relative_to(root)}) ==")
            for r in report.requirements:
                typer.echo(f"  {r.id}: {r.drift.value}" + (f" ({;})".replace(";", ";") if r.details else ""))
                for d in r.details:
                    typer.echo(f"    - {d}")
            typer.echo("")

    if json_output:
        out = {
            "reports": [
                {
                    "spec_id": r.spec_id,
                    "requirements": [
                        {"id": x.id, "drift": x.drift.value, "details": x.details}
                        for x in r.requirements
                    ],
                }
                for r in reports
            ],
            "has_drift": any_drift,
        }
        typer.echo(json.dumps(out, indent=2))

    if record:
        for sp in sorted(spec_paths):
            try:
                spec = spec_sync.parse_spec_file(sp)
            except Exception as e:
                typer.echo(f"Failed to parse {sp} for record: {e}", err=True)
                raise typer.Exit(1)
            state_path = sp.parent / ".sync.json"
            state_new = spec_sync.record_state(spec, root)
            spec_sync.save_state(state_path, state_new)
            typer.echo(f"Recorded sync state: {state_path.relative_to(root)}")

    if any_drift:
        raise typer.Exit(1)
    raise typer.Exit(0)
